-- demo 프로필의 비어 있는 시연 DB에서만 실행. 구장 사진은 서버 정적 리소스 사용.
SET time_zone = '+09:00';
START TRANSACTION;
SET @demo_city = (SELECT id FROM cities WHERE name = '서울특별시');
SET @demo_area_0 = (SELECT id FROM areas WHERE cities_id = @demo_city AND name = '은평구');
SET @demo_area_1 = (SELECT id FROM areas WHERE cities_id = @demo_city AND name = '서대문구');
SET @demo_area_2 = (SELECT id FROM areas WHERE cities_id = @demo_city AND name = '마포구');
SET @demo_area_3 = (SELECT id FROM areas WHERE cities_id = @demo_city AND name = '강남구');
COMMIT;
